const orgModel = require('../models/org.model');
const ObjectId = require('mongoose').Types.ObjectId;
const stream = require('stream');
const moment = require('moment')
const {
    capitalizeFirstLetter
} = require('./helper.functions')
const { checkIsUK } = require('./benchmarkData.helper');
const { applyWorksheetZoom } = require("./excelZoom");
let HEADER_COLOR = '2E1065';
let FONT_COLOR = 'F3F4F5';
let SECONDARY_HEADER_COLOR = '2E1065';
const FONT_FAMILY = 'Calibri';

const VERBATIM_REPORT_TITLE_FONT_STYLE = {
    color: {argb: FONT_COLOR},
    bold: true,
    size: 30,
    name: FONT_FAMILY,
};
const VERBATIM_REPORT_TITLE_FILL_STYLE = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: {argb: HEADER_COLOR},
    // bgColor: {argb: '000000'},
};

const VERBATIM_REPORT_SUBTITLE_FONT_STYLE = {
    color: {argb: FONT_COLOR},
    size: 25,
    name: FONT_FAMILY,
};

const VERBATIM_REPORT_SUBTITLE_FILL_STYLE = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: {argb: HEADER_COLOR},
    // bgColor: {argb: '000000'},
};

async function generateVerbatimReport(dataStream, questionsHash, workbook, req) {
    // TODO: Use row number based on these values
    const reportTitleCellNumber = 1;
    const reportSubTitleCellNumber = 2;
    const reportQuestionCellNumber = 4;
    const reportAnswerFirstCellNumber = 5;
    let orgData = await orgModel.findOne({_id: ObjectId(req.organizationProgramData.organizationId)})
    const isUK = checkIsUK(req);
    const timeFormat = isUK ? 'D MMMM YYYY' : 'MMMM D, YYYY';
    const title = "EMPLOYEE VERBATIMS";
    const subTitle = `ORGANIZATION: ${orgData.Alias_Company_Name || orgData.Account_Name}
						PROGRAM: VERMONT 2022
						SURVEY DATES: ${moment(req.program?.EFS_Launch_Date).format(timeFormat)} to ${moment(req.program?.EFS_end_Date).format(timeFormat)}`;
    let index = 0;

    dataStream.pipe(new stream.Transform({
        objectMode: true,
        transform: (questionData, encoding, callback) => {
            const processedRow = {
                question: questionsHash[questionData._id],
                ...questionData,
            };
            const workSheet = workbook.addWorksheet(`Verbatims Q${index + 1}`);
            applyWorksheetZoom(workSheet, 75);
            // Column config
            const column = workSheet.getColumn(1);
            column.alignment = {wrapText: true};
            column.width = 140;
            column.font = {name: FONT_FAMILY, font: 20};
            const imageId1 = workbook.media.push({
                base64: 'data:image/png;base64,',
                extension: 'png',
            });
            // workSheet.autoFilter = {
            //     from: `A${reportQuestionCellNumber}`,
            //     to: `A${processedRow.answers.length + reportAnswerFirstCellNumber}`,
            // };
            workSheet.addConditionalFormatting({
                ref: `A${reportAnswerFirstCellNumber}:A${questionData.answers.length + reportAnswerFirstCellNumber - 1}`,
                rules: [
                    {
                        type: "expression",
                        formulae: ["MOD(ROW()+COLUMN(),2)=0"],
                        style: {
                            fill: {
                                type: "pattern",
                                pattern: "solid",
                                bgColor: {argb: "ECECEC"},
                            },
                        },
                    },
                ],
            });

            let firstCell = workSheet.getCell('1', '1');
            firstCell.fill = {
                type: 'pattern',
                pattern: 'solid',
                fgColor: {argb: HEADER_COLOR},
                // bgColor: {argb: '000000'},
            };
            // firstCell.value = 'Отчет по вопросу';

            let titleCell = workSheet.getCell('2', '1');
            titleCell.font = VERBATIM_REPORT_TITLE_FONT_STYLE;
            titleCell.fill = VERBATIM_REPORT_TITLE_FILL_STYLE;
            titleCell.value = title;

            let subTitleCell = workSheet.getCell('3', '1');
            subTitleCell.font = VERBATIM_REPORT_SUBTITLE_FONT_STYLE;
            subTitleCell.fill = VERBATIM_REPORT_SUBTITLE_FILL_STYLE;
            subTitleCell.value = subTitle;

            // subTitleColumn.commit();

            // Add empty row
            // workSheet.addRow().commit();
            console.log("Hello")
            // add image to first cell
            workSheet.addImage(0, 'A1:A1');
            // Add question row
            const questionRow = workSheet.addRow([processedRow.question.caption]);
            workSheet.getCell('4', '1').fill = {
                type: 'pattern',
                pattern: 'solid',
                fgColor: {argb: SECONDARY_HEADER_COLOR},
                // bgColor: {argb: '000000'},
            };
            questionRow.font = {
                color: {argb: FONT_COLOR},
                bold: true,
                size: 25,
                name: "calibri",
            };
            questionRow.commit();

            processedRow.answers.forEach((answer) => {
                let answerRow = workSheet.addRow([capitalizeFirstLetter(answer)])
                answerRow.font = {
                    size: 16,
                    name: "calibri",
                };
                answerRow.commit();
            });

            index++;
            workSheet.commit();
            callback();
        }
    }));

    dataStream.on('end', () => {
        workbook.commit();
    });
    dataStream.on('error', (error) => {
        console.log("ERROR in reading streaming verbatim report!", error);
        throw new Error(error);
    });
}

module.exports = {
    generateVerbatimReport
}
